<script lang="ts">
 import { page } from '$app/state'; import { onMount } from 'svelte'; import PageHeader from '$lib/components/PageHeader.svelte'; import { listDepartments, listDepartmentProjects } from '$lib/api/departments'; import type { DepartmentView, ProjectView } from '$lib/api/types';
 const id=$derived(String(page.params.departmentId ?? '')); let department=$state<DepartmentView|null>(null), all=$state<DepartmentView[]>([]), projects=$state<ProjectView[]>([]), loading=$state(true), errorMessage=$state(''); onMount(async()=>{try{const[d,p]=await Promise.all([listDepartments(),listDepartmentProjects(id)]);all=d.data.items;department=all.find(item=>item.id===id)||null;projects=p.data.items}catch(e){errorMessage=e instanceof Error?e.message:'部门详情加载失败'}finally{loading=false}}); const children=$derived(all.filter(d=>d.parent_id===id));
</script>
{#if loading}<section class="workspace-card state-box">正在加载部门详情…</section>{:else if department}<PageHeader title={department.name} eyebrow={department.code} description="部门下级信息与关联项目。" /><div class="page-grid"><section class="workspace-card"><h2>部门信息</h2><dl><div><dt>部门编码</dt><dd>{department.code}</dd></div><div><dt>下级部门</dt><dd>{children.length} 个</dd></div></dl><div class="child-list">{#each children as child}<a href={`/departments/${child.id}`}><strong>{child.name}</strong><span>{child.code}</span></a>{:else}<p class="empty-inline">没有下级部门。</p>{/each}</div></section><section class="workspace-card"><h2>关联项目</h2><div class="project-list">{#each projects as project}<a href={`/projects/${project.project_key}`}><strong>{project.project_key} · {project.name}</strong><span>{project.description||'暂无描述'}</span></a>{:else}<p class="empty-inline">没有可见的关联项目。</p>{/each}</div></section></div>{:else}<section class="workspace-card error-state">{errorMessage||'部门不存在'}</section>{/if}
<style>.page-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:18px}.workspace-card h2{margin-top:0}dl{display:grid;gap:10px}dl div{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--color-border)}dt{color:var(--color-text-muted)}dd{margin:0;font-weight:700}.child-list,.project-list{display:grid;gap:8px;margin-top:18px}.child-list a,.project-list a{display:grid;gap:4px;padding:11px;border-radius:9px;background:#f7f8fb}.child-list span,.project-list span{color:var(--color-text-muted);font-size:13px}.error-state{color:var(--color-danger)}.state-box{text-align:center;color:var(--color-text-muted)}@media(max-width:760px){.page-grid{grid-template-columns:1fr}}</style>
